    is_central_warehouse = models.IntegerField(blank=True, null=True)
    cin = models.CharField(max_length=255)
    gst = models.IntegerField()
    pan_no = models.CharField(max_length=100)
    art = models.CharField(max_length=100)
    pharmacist_name = models.CharField(max_length=255)
    pharmacist_registration = models.CharField(max_length=255)
