    medicine_others = models.TextField()
    consultation_other = models.TextField()
    center_location = models.TextField()
    add_date = models.DateTimeField()
    status = models.IntegerField()
    operate_other = models.IntegerField()
    upload_photo_1 = models.CharField(max_length=255)

    class Meta:
        managed = False
        db_table = 'hms_centers'


