class ReportsPatientCNB(models.Model):
    # If patient_id links to an existing Patient table, use a ForeignKey instead.
    # Otherwise, an IntegerField or CharField works. The JSON had "15" (string).
    patient_id = models.CharField(max_length=50) 
    quality = models.CharField(max_length=50)
    fc_comment = models.TextField(blank=True, null=True)
    latest_connected_date = models.DateField(blank=True, null=True)
    
    # Optional timestamps to track when data was added/edited
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    def __str__(self):
        return f"Patient {self.patient_id} - {self.quality}"        
